  "상시 파밍 가능한 스테이지만 (이벤트 한정 제외)": ["Permanently farmable stages only (exclude limited events)", "常時周回可能なステージのみ（期間限定イベント除外）"],
  "조건에 맞는 재료가 없어요.": ["No materials match these filters.", "条件に合う素材がありません。"],
