  "AI 요약은 아직 준비 중이에요. 지금은 게임 내 스토리 전문으로 만나 보세요.": ["The AI digest isn't ready yet — enjoy the full in-game story script for now.", "AI要約はまだ準備中です。今はゲーム内ストーリー全文をお楽しみください。"],
