  "소장품·자원 카드의 「＋ 보유」 버튼으로 담아두고 여기서 한눈에 봅니다": ["Save items with the \"+ Add\" button on collectible/resource cards, then review them all here", "秘宝・リソースカードの「＋ 所持」ボタンで登録し、ここで一覧できます"],
  "게임에서 얻은 소장품·자원을 담아두는 목록입니다. 카드의 「＋ 보유」 버튼으로 추가하며, 이 브라우저에 테마별로 저장됩니다.": ["A personal list of the collectibles and resources you own in-game. Add items with the \"+ Add\" button on each card — saved per theme in this browser.", "ゲームで獲得した秘宝・リソースを登録しておく個人リストです。各カードの「＋ 所持」ボタンで追加でき、このブラウザにテーマ別に保存されます。"],
  "아직 담은 항목이 없습니다 — 소장품·전시관 카드의 「＋ 보유」 버튼으로 추가하세요.": ["Nothing saved yet — use the \"+ Add\" button on collectible/exhibition cards.", "まだ何も登録されていません — 秘宝・展示館カードの「＋ 所持」ボタンで追加してください。"],
