  "난이도 14 이상: 정예·리더가 등장 후 20초간 공격력 +30%, 받는 물리·마법 대미지 -50%": ["Difficulty 14+: elites/leaders gain +30% ATK and take -50% physical/arts damage for 20s after appearing", "難易度14以上：精鋭・リーダーは登場後20秒間、攻撃力+30%・受ける物理/術ダメージ-50%"],
